371→export type ServerMessage =
372→  | ServerRelay
373→  | ServerStatus
374→  | ServerError
375→  | ServerAgentList
376→  | ServerSpawned
377→  | ServerMessageHistory
378→  | ServerCliDisconnected
379→  | ServerCliConnected
380→  | ServerHistoryCleared
381→  | ServerWorkspaceList
382→  | ServerDirectoryListing
383→  | ServerTaskList
384→  | ServerTaskUpdated
385→  | ServerTaskDeleted;
386→
387→// ── UI state ──────────────────────────────────────────────────────────────
388→
389→/**
390→ * Lifecycle states of the Claude agent process:
391→ * - `idle`      — no process running, ready to spawn
392→ * - `spawning`  — process launched, waiting for CLI to connect via WS
393→ * - `connected` — CLI connected and `system/init` received
394→ * - `thinking`  — waiting for assistant response
395→ * - `done`      — `result` message received, process finished
396→ * - `error`     — process crashed or unexpected failure
397→ */
398→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
399→
400→export type ChatMessageRole = "user" | "assistant" | "system";
401→
402→/**
403→ * A single entry in the chat message list. System messages include
404→ * session init info and result summaries. Messages with a `controlRequest`
405→ * are rendered as tool-approval cards instead of plain bubbles.
406→ */
407→/** A single option in an AskUserQuestion question. */
408→export interface UserQuestionOption {
409→  label: string;
410→  description?: string;
411→}
412→
413→/** A single question from AskUserQuestion. */
414→export interface UserQuestion {
415→  question: string;
416→  header?: string;
417→  options: UserQuestionOption[];
418→  multiSelect: boolean;
419→}
420→
421→/** Info about a single tool_use block in an assistant message. */
422→export interface ToolCallInfo {
423→  name: string;
424→  toolUseId?: string;
425→  /** Truncated one-line preview of the tool result, if available. */
426→  resultPreview?: string;
427→  /** Raw tool input data, preserved for file-modifying tools (Edit, Write, MultiEdit). */
428→  input?: Record<string, unknown>;
429→}
430→
431→export interface ChatMessage {
432→  id: string;
433→  role: ChatMessageRole;
434→  content: string;
435→  timestamp: number;
436→  /** Present when this message represents a tool approval request. */
437→  controlRequest?: {
438→    id: string;
439→    tool_name: string;
440→    input: Record<string, unknown>;
441→    /** Tool description from the protocol, if available. */
442→    description?: string;
443→    /** Set to true after the user allows or denies. */
444→    resolved?: boolean;
445→    /** Whether the user allowed (true) or denied (false). */
446→    allowed?: boolean;
447→  };
448→  /** Present when this message is an AskUserQuestion control request. */
449→  userQuestion?: {
450→    requestId: string;
451→    questions: UserQuestion[];
452→    resolved?: boolean;
453→  };
454→  /** Tool calls found in this assistant message. */
455→  toolCalls?: ToolCallInfo[];
456→  /** True when this message has only tool_use/tool_result blocks and no text. */
457→  isToolOnly?: boolean;
458→}
459→
460→// ── Task system ──────────────────────────────────────────────────────────
461→
462→export type TaskStatus = "icebox" | "todo" | "in-progress" | "done";
463→export type TaskPriority = "low" | "medium" | "high" | "urgent";
464→
465→/** A user-created task, optionally linked to a Claude agent. */
466→export interface Task {
467→  id: string;
468→  title: string;
469→  description: string;
470→  status: TaskStatus;
471→  priority: TaskPriority;
472→  /** If delegated, the agentId of the spawned Claude agent. */
473→  agentId: string | null;
474→  /** Workspace this task belongs to. */
475→  workspaceId: string | null;
476→  createdAt: number;
477→  updatedAt: number;
478→}
479→

