  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→  Workspace,
 65→} from "@/lib/types";
 66→import { sfxTool, sfxDone, sfxError, sfxQuestion, sfxBegin, sfxSend } from "@/lib/sfx";
 67→
 68→/** Connect to the WS server on the same host the page was loaded from. */
 69→const WS_URL =
 70→  typeof window !== "undefined"
 71→    ? `ws://${window.location.hostname}:9900/browser`
 72→    : "ws://localhost:9900/browser";
 73→
 74→/** Per-agent client state. */
 75→export interface AgentClientState {
 76→  status: AgentStatus;
 77→  messages: ChatMessage[];
 78→  /** Raw Claude NDJSON messages for debug view. */
 79→  rawMessages: ClaudeMessage[];
 80→  label: string;
 81→  tmuxSession: string | null;
 82→  createdAt: number;
 83→  /** Model name from system/init or agent_list. */
 84→  model?: string;
 85→}
 86→
 87→/**
 88→ * Extract displayable text from a Claude assistant message.
 89→ * Content blocks may be text, tool_use, or tool_result — each is
 90→ * handled defensively since the array structure can vary.
 91→ */
 92→function extractText(msg: ClaudeAssistant): string {
 93→  const blocks = msg.message?.content;
 94→  if (!blocks || !Array.isArray(blocks)) return "";
 95→  return blocks
 96→    .map((b) => {
 97→      if (b.type === "text") return b.text;
 98→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 99→      if (b.type === "tool_result") {
100→        const c = (b as { content?: unknown }).content;
101→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
102→      }
103→      return "";
104→    })
105→    .filter(Boolean)
106→    .join("\n");
107→}
108→
109→/** Module-level counter for generating unique message IDs. */
110→let msgCounter = 0;
111→function nextId() {
112→  return `msg-${Date.now()}-${++msgCounter}`;
113→}
114→
115→/**
116→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
117→ * Used both for live messages and for replaying message_history.
118→ */
119→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
120→  if (relayMsg.type === "relay") {
121→    const msg = relayMsg.message;
122→
123→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
124→      const init = msg as ClaudeSystemInit;
125→      return {
126→        id: nextId(),
127→        role: "system",
128→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
129→        timestamp: Date.now(),
130→      };
131→    }
132→
133→    if (msg.type === "user") {
134→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
135→      // Only render human-typed user messages (string content).
136→      // CLI tool_result messages have array content — these are internal
137→      // protocol messages and are only visible in the raw message viewer.
138→      if (typeof rawContent !== "string") return null;
139→      if (!rawContent.trim()) return null;
140→      return {
141→        id: nextId(),
142→        role: "user",
143→        content: rawContent,
144→        timestamp: Date.now(),
145→      };
146→    }
147→
148→    if (msg.type === "assistant") {
149→      const assistant = msg as ClaudeAssistant;
150→      const text = extractText(assistant);
151→      if (!text) return null;
152→
153→      const blocks = assistant.message?.content ?? [];
154→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
155→
156→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
157→      const resultMap = new Map<string, string>();
158→      for (const b of blocks) {
159→        if (b.type === "tool_result") {
160→          const tr = b as { tool_use_id?: string; content?: unknown };
161→          if (tr.tool_use_id) {
162→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
163→            const firstLine = raw.split("\n")[0];
164→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
165→          }
166→        }
167→      }
168→
169→      // Build ToolCallInfo for each tool_use block. For file-modifying tools
170→      // (Edit, Write, MultiEdit), the raw `input` object is preserved so that
171→      // DiffViewer can render syntax-highlighted before/after diffs. Other
172→      // tools only keep the name and result preview to avoid carrying
173→      // unnecessary data (e.g. Read file contents, Bash output).
174→      const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
175→      const toolCalls: ToolCallInfo[] = blocks
176→        .filter((b) => b.type === "tool_use")
177→        .map((b) => {
178→          const tu = b as { name: string; id: string; input: Record<string, unknown> };
179→          const info: ToolCallInfo = {
180→            name: tu.name,
181→            toolUseId: tu.id,
182→            resultPreview: resultMap.get(tu.id),
183→          };
184→          if (DIFF_TOOLS.has(tu.name)) {
185→            info.input = tu.input;
186→          }
187→          return info;
188→        });
189→      const isToolOnly = !hasText && toolCalls.length > 0;
190→
191→      return {
192→        id: nextId(),
193→        role: "assistant",
194→        content: text,
195→        timestamp: Date.now(),
196→        toolCalls,
197→        isToolOnly,
198→      };
199→    }
200→
201→    if (msg.type === "result") {
202→      const result = msg as ClaudeResult;
203→      const summary = result.is_error
204→        ? `Error: ${result.error}`
205→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
206→      return {
207→        id: nextId(),
208→        role: "system",
209→        content: summary,
210→        timestamp: Date.now(),
211→      };
212→    }
213→
214→    if (msg.type === "control_request") {
215→      const cr = msg as ClaudeControlRequest;
216→
217→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
218→      if (cr.request.tool_name === "AskUserQuestion") {
219→        const input = cr.request.input as { questions?: UserQuestion[] };
220→        const questions = Array.isArray(input.questions) ? input.questions : [];
221→        return {
222→          id: nextId(),
223→          role: "system",
224→          content: "Question from Claude",
225→          timestamp: Date.now(),
226→          userQuestion: {
227→            requestId: cr.request_id,
228→            questions,
229→          },
230→        };
231→      }
232→
233→      return {
234→        id: nextId(),
235→        role: "system",
236→        content: `Tool approval requested: ${cr.request.tool_name}`,
237→        timestamp: Date.now(),
238→        controlRequest: {
239→          id: cr.request_id,
240→          tool_name: cr.request.tool_name,
241→          input: cr.request.input,
242→          description: cr.request.description,
243→        },
244→      };
245→    }
246→  }
247→
248→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
249→    return {
250→      id: nextId(),
251→      role: "system",
252→      content: `Error: ${relayMsg.error}`,
253→      timestamp: Date.now(),
254→    };
255→  }
256→
257→  return null;
258→}
259→
260→/** Console logger with [thos] prefix for easy filtering. */
261→function log(...args: unknown[]) {
262→  console.log("[thos-ws]", ...args);
263→}
264→
265→export function useWebSocket() {
266→  const wsRef = useRef<WebSocket | null>(null);
267→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
268→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
269→  const closingRef = useRef(false);
270→  const [connected, setConnected] = useState(false);
271→  /** True once we've received the initial agent_list from the server. */
272→  const [initialLoadDone, setInitialLoadDone] = useState(false);
273→
274→  // Multi-agent state
275→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
276→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
277→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
278→
279→  // Task state
280→  const [tasks, setTasks] = useState<Task[]>([]);
281→
282→  // Workspace state
283→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
284→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
285→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
286→
287→  // Per-agent deduplication: track count of processed messages per agent
288→  // to avoid duplicating messages already in local state during history replay.
289→  const processedCountRef = useRef<Map<string, number>>(new Map());
290→
291→  // Track which agents have had their history loaded (lazy loading).
292→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
293→
294→  /** Immutably update a single agent's state in the Map. */
295→  const updateAgent = useCallback(
296→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
297→      setAgents((prev) => {
298→        const existing = prev.get(agentId);
299→        if (!existing) return prev;
300→        const next = new Map(prev);
301→        next.set(agentId, updater(existing));
302→        return next;
303→      });
304→    },
305→    []
306→  );
307→
308→  const connect = useCallback(() => {
309→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
310→    if (wsRef.current) {
311→      wsRef.current.close();
312→      wsRef.current = null;
313→    }
314→
315→    // Reset dedup counts on new connection — server will send fresh history
316→    processedCountRef.current.clear();
317→    setInitialLoadDone(false);
318→    setLoadedAgents(new Set());
319→
320→    log("connecting to", WS_URL);
321→    const ws = new WebSocket(WS_URL);
322→    wsRef.current = ws;
323→
324→    ws.onopen = () => {
325→      log("connected");
326→      setConnected(true);
327→    };
328→
329→    ws.onclose = () => {
330→      log("disconnected, closingRef =", closingRef.current);
331→      setConnected(false);
332→      wsRef.current = null;
333→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
334→      if (closingRef.current) return;
335→      // Reconnection guard: clear any existing timer before scheduling
336→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
337→      log("scheduling reconnect in 2s");
338→      reconnectTimer.current = setTimeout(() => connect(), 2000);
339→    };
340→
341→    ws.onerror = (e) => {
342→      log("error", e);
343→      // onclose will fire after onerror, which triggers reconnect
344→    };
345→
346→    ws.onmessage = (event) => {
347→      let data: ServerMessage;
348→      try {
349→        data = JSON.parse(event.data as string);
350→      } catch {
351→        return;
352→      }
353→
354→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
355→
356→      // ── workspace_list: full workspace list from server ──
357→      if (data.type === "workspace_list") {
358→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
359→        log("workspace_list:", wsList.length, "workspaces");
360→        setWorkspaces(wsList);
361→        return;
362→      }
363→
364→      // ── directory_listing: response to browse_directory ──
365→      if (data.type === "directory_listing") {
366→        const listing = data as { path: string; entries: DirectoryEntry[] };
367→        log("directory_listing:", listing.path, listing.entries.length, "entries");
368→        setDirectoryListing({ path: listing.path, entries: listing.entries });
369→        return;
370→      }
371→
372→      // ── task_list: full task list from server ──
373→      if (data.type === "task_list") {
374→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
375→        setTasks((data as ServerTaskList).tasks);
376→        return;
377→      }
378→
379→      // ── task_updated: single task changed ──
380→      if (data.type === "task_updated") {
381→        const updated = (data as ServerTaskUpdated).task;
382→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
383→        return;
384→      }
385→
386→      // ── task_deleted: remove task ──
387→      if (data.type === "task_deleted") {
388→        const deletedId = (data as ServerTaskDeleted).taskId;
389→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
390→        return;
391→      }
392→
393→      // ── message_history: replay full history from server ──
394→      if (data.type === "message_history") {
395→        const historyMsg = data as ServerMessageHistory;
396→        const agentId = historyMsg.agentId;
397→        const serverMessages = historyMsg.messages;
398→        log("message_history:", agentId, serverMessages.length, "raw msgs");
399→
400→        // Convert all server messages to ChatMessages + extract raw Claude messages
401→        const chatMessages: ChatMessage[] = [];
402→        const rawMessages: ClaudeMessage[] = [];
403→        for (const sm of serverMessages) {
404→          if (sm.type === "relay") {
405→            rawMessages.push(sm.message);
406→          }
407→          const cm = relayChatMessage(agentId, sm);
408→          if (cm) chatMessages.push(cm);
409→        }
410→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
411→
412→        // Always replace local messages with server history (source of truth).
413→        setAgents((prev) => {
414→          const existing = prev.get(agentId);
415→          if (!existing) {
416→            log("message_history:", agentId, "agent not in map yet, creating");
417→            const next = new Map(prev);
418→            next.set(agentId, {
419→              status: "idle",
420→              messages: chatMessages,
421→              rawMessages,
422→              label: "",
423→              tmuxSession: null,
424→              createdAt: 0,
425→            });
426→            return next;
427→          }
428→          const next = new Map(prev);
429→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
430→          return next;
431→        });
432→
433→        processedCountRef.current.set(agentId, chatMessages.length);
434→        setLoadedAgents((prev) => {
435→          if (prev.has(agentId)) return prev;
436→          const next = new Set(prev);
437→          next.add(agentId);
438→          return next;
439→        });
440→        return;
441→      }
442→
443→      // ── history_cleared: wipe local messages for this agent ──
444→      if (data.type === "history_cleared") {
445→        updateAgent(data.agentId, (prev) => ({
446→          ...prev,
447→          messages: [],
448→          rawMessages: [],
449→        }));
450→        processedCountRef.current.set(data.agentId, 0);
451→        return;
452→      }
453→
454→      // ── cli_disconnected: show system message ──
455→      if (data.type === "cli_disconnected") {
456→        updateAgent(data.agentId, (prev) => ({
457→          ...prev,
458→          messages: [
459→            ...prev.messages,
460→            {
461→              id: nextId(),
462→              role: "system",
463→              content: "CLI session ended",
464→              timestamp: Date.now(),
465→            },
466→          ],
467→        }));
468→        return;
469→      }
470→
471→      // ── cli_connected: show system message ──
472→      if (data.type === "cli_connected") {
473→        updateAgent(data.agentId, (prev) => ({
474→          ...prev,
475→          messages: [
476→            ...prev.messages,
477→            {
478→              id: nextId(),
479→              role: "system",
480→              content: "CLI reconnected",
481→              timestamp: Date.now(),
482→            },
483→          ],
484→        }));
485→        return;
486→      }
487→
488→      // ── agent_list: reconcile sidebar state from server ──
489→      if (data.type === "agent_list") {
490→        const serverAgents = data.agents as AgentInfo[];
491→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
492→        setAgents((prev) => {
493→          const next = new Map(prev);
494→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
495→
496→          // Update or add agents from server
497→          for (const info of serverAgents) {
498→            const existing = next.get(info.agentId);
499→            if (existing) {
500→              next.set(info.agentId, {
501→                ...existing,
502→                status: info.status,
503→                tmuxSession: info.tmuxSession,
504→                label: info.label,
505→                model: info.model ?? existing.model,
506→              });
507→            } else {
508→              next.set(info.agentId, {
509→                status: info.status,
510→                messages: [],
511→                rawMessages: [],
512→                label: info.label,
513→                tmuxSession: info.tmuxSession,
514→                createdAt: info.createdAt,
515→                model: info.model ?? undefined,
516→              });
517→            }
518→          }
519→
520→          // Remove agents no longer on the server
521→          for (const id of next.keys()) {
522→            if (!serverIds.has(id)) {
523→              next.delete(id);
524→            }
525→          }
526→
527→          return next;
528→        });
529→        setAgentOrder(serverAgents.map((a) => a.agentId));
530→        setInitialLoadDone(true);
531→
532→        // Auto-select the first agent on initial load when nothing is selected
533→        setActiveAgentId((prev) => {
534→          if (prev !== null) return prev;
535→          if (serverAgents.length === 0) return null;
536→          return serverAgents[0].agentId;
537→        });
538→        return;
539→      }
540→
541→      // ── spawned: auto-select the newly created agent ──
542→      if (data.type === "spawned") {
543→        setActiveAgentId(data.agentId);
544→        return;
545→      }
546→
547→      // ── status: update a specific agent's status ──
548→      if (data.type === "status") {
549→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
550→        return;
551→      }
552→
553→      // ── error: append to agent's message list ──
554→      if (data.type === "error") {
555→        sfxError();
556→        updateAgent(data.agentId, (prev) => ({
557→          ...prev,
558→          messages: [
559→            ...prev.messages,
560→            {
561→              id: nextId(),
562→              role: "system",
563→              content: `Error: ${data.error}`,
564→              timestamp: Date.now(),
565→            },
566→          ],
567→        }));
568→        // Track processed count for dedup
569→        processedCountRef.current.set(
570→          data.agentId,
571→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
572→        );
573→        return;
574→      }
575→
576→      // ── relay: append claude message to agent's history ──
577→      if (data.type === "relay") {
578→        const agentId = data.agentId;
579→        const rawMsg = data.message;
580→        const chatMsg = relayChatMessage(agentId, data);
581→
582→        // SFX: play a sound for each tool call in the message
583→        if (chatMsg?.toolCalls?.length) {
584→          // Play SFX for the first mapped tool (avoids overlapping sounds in multi-tool messages)
585→          const first = chatMsg.toolCalls.find((tc) => tc.name);
586→          if (first) sfxTool(first.name);
587→        }
588→
589→        // SFX: result done / error
590→        if (rawMsg.type === "result") {
591→          const result = rawMsg as ClaudeResult;
592→          if (result.is_error) sfxError();
593→          else sfxDone();
594→        }
595→
596→        // SFX: control request (tool approval / question)
597→        if (rawMsg.type === "control_request") {
598→          sfxQuestion();
599→        }
600→
601→        // SFX: session start
602→        if (rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init") {
603→          sfxBegin();
604→        }
605→
606→        // Capture model from system/init
607→        const initModel =
608→          rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init"
609→            ? (rawMsg as ClaudeSystemInit).model
610→            : undefined;
611→
612→        updateAgent(agentId, (prev) => ({
613→          ...prev,
614→          rawMessages: [...prev.rawMessages, rawMsg],
615→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
616→          ...(initModel ? { model: initModel } : {}),
617→        }));
618→        if (chatMsg) {
619→          // Track processed count for dedup
620→          processedCountRef.current.set(
621→            agentId,
622→            (processedCountRef.current.get(agentId) ?? 0) + 1
623→          );
624→        }
625→        return;
626→      }
627→    };
628→  }, [updateAgent]);
629→
630→  useEffect(() => {
631→    closingRef.current = false;
632→    connect();
633→    return () => {
634→      closingRef.current = true;
635→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
636→      wsRef.current?.close();
637→    };
638→  }, [connect]);
639→
640→  const send = useCallback((data: object) => {
641→    if (wsRef.current?.readyState === WebSocket.OPEN) {
642→      wsRef.current.send(JSON.stringify(data));
643→    }
644→  }, []);
645→
646→  // Request history for the active agent if not already loaded.
647→  useEffect(() => {
648→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
649→    log("requesting history for", activeAgentId);
650→    send({ type: "request_history", agentId: activeAgentId });
651→  }, [activeAgentId, loadedAgents, send]);
652→
653→  const spawnAgent = useCallback(
654→    (prompt: string, model?: string) => {
655→      send({ type: "spawn", prompt, ...(model ? { model } : {}) });
656→    },
657→    [send]
658→  );
659→
660→  const sendMessage = useCallback(
661→    (content: string) => {
662→      if (!activeAgentId) return;
663→      // Optimistically add user message to local state
664→      updateAgent(activeAgentId, (prev) => ({
665→        ...prev,
666→        messages: [
667→          ...prev.messages,
668→          {
669→            id: nextId(),
670→            role: "user",
671→            content,
672→            timestamp: Date.now(),
673→          },
674→        ],
675→      }));
676→      send({ type: "send_message", agentId: activeAgentId, content });
677→      sfxSend();
678→    },
679→    [send, activeAgentId, updateAgent]
680→  );
681→
682→  const respondToControl = useCallback(
683→    (requestId: string, allow: boolean) => {
684→      if (!activeAgentId) return;
685→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
686→      updateAgent(activeAgentId, (prev) => ({
687→        ...prev,
688→        messages: prev.messages.map((m) =>
689→          m.controlRequest?.id === requestId
690→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
691→            : m
692→        ),
693→      }));
694→    },
695→    [send, activeAgentId, updateAgent]
696→  );
697→
698→  /** Respond to an AskUserQuestion control request with the user's selections. */
699→  const respondToUserQuestion = useCallback(
700→    (requestId: string, answers: Record<string, string>) => {
701→      if (!activeAgentId) return;
702→      send({
703→        type: "control_response",
704→        agentId: activeAgentId,
705→        request_id: requestId,
706→        allow: true,
707→        answers,
708→      });
709→      updateAgent(activeAgentId, (prev) => ({
710→        ...prev,
711→        messages: prev.messages.map((m) =>
712→          m.userQuestion?.requestId === requestId
713→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
714→            : m
715→        ),
716→      }));
717→    },
718→    [send, activeAgentId, updateAgent]
719→  );
720→
721→  // ── Agent management actions ──────────────────────────────────────────────
722→
723→  const killAgent = useCallback(
724→    (agentId: string) => {
725→      send({ type: "kill_agent", agentId });
726→    },
727→    [send]
728→  );
729→
730→  const deleteAgent = useCallback(
731→    (agentId: string) => {
732→      send({ type: "delete_agent", agentId });
733→      // Deselect if we just deleted the active agent
734→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
735→    },
736→    [send]
737→  );
738→
739→  const renameAgent = useCallback(
740→    (agentId: string, label: string) => {
741→      send({ type: "rename_agent", agentId, label });
742→    },
743→    [send]
744→  );
745→
746→  const clearHistory = useCallback(
747→    (agentId: string) => {
748→      send({ type: "clear_history", agentId });
749→    },
750→    [send]
751→  );
752→
753→  // ── Task actions ──────────────────────────────────────────────────────────
754→
755→  const createTask = useCallback(
756→    (title: string, description: string, priority: TaskPriority) => {
757→      send({ type: "create_task", title, description, priority });
758→    },
759→    [send]
760→  );
761→
762→  const updateTask = useCallback(
763→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
764→      send({ type: "update_task", taskId, updates });
765→    },
766→    [send]
767→  );
768→
769→  const deleteTask = useCallback(
770→    (taskId: string) => {
771→      send({ type: "delete_task", taskId });
772→    },
773→    [send]
774→  );
775→
776→  const delegateTask = useCallback(
777→    (taskId: string) => {
778→      send({ type: "delegate_task", taskId });
779→    },
780→    [send]
781→  );
782→
783→  // ── Workspace actions ──────────────────────────────────────────────────────
784→
785→  const setActiveWorkspaceId = useCallback(
786→    (workspaceId: string | null) => {
787→      setActiveWorkspaceIdState(workspaceId);
788→      send({ type: "set_workspace", workspaceId });
789→    },
790→    [send]
791→  );
792→
793→  const createWorkspace = useCallback(
794→    (name: string, cwd: string) => {
795→      send({ type: "create_workspace", name, cwd });
796→    },
797→    [send]
798→  );
799→
800→  const renameWorkspace = useCallback(
801→    (workspaceId: string, name: string) => {
802→      send({ type: "rename_workspace", workspaceId, name });
803→    },
804→    [send]
805→  );
806→
807→  const deleteWorkspace = useCallback(
808→    (workspaceId: string) => {
809→      send({ type: "delete_workspace", workspaceId });
810→      setActiveWorkspaceIdState((prev) => (prev === workspaceId ? null : prev));
811→    },
812→    [send]
813→  );
814→
815→  const browseDirectory = useCallback(
816→    (path: string) => {
817→      send({ type: "browse_directory", path });
818→    },
819→    [send]
820→  );
821→
822→  // Derived values for the active agent
823→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
824→  const activeStatus = useMemo<AgentStatus>(
825→    () => activeAgent?.status ?? "idle",
826→    [activeAgent?.status]
827→  );
828→  const activeMessages = useMemo<ChatMessage[]>(
829→    () => activeAgent?.messages ?? [],
830→    [activeAgent?.messages]
831→  );
832→  const activeRawMessages = useMemo<ClaudeMessage[]>(
833→    () => activeAgent?.rawMessages ?? [],
834→    [activeAgent?.rawMessages]
835→  );
836→  const activeModel = activeAgent?.model ?? null;
837→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
838→
839→  return {
840→    connected,
841→    initialLoadDone,
842→    historyLoading,
843→    agents,
844→    agentOrder,
845→    activeAgentId,
846→    setActiveAgentId,
847→    activeStatus,
848→    activeMessages,
849→    activeRawMessages,
850→    activeModel,
851→    spawnAgent,
852→    sendMessage,
853→    respondToControl,
854→    respondToUserQuestion,
855→    killAgent,
856→    deleteAgent,
857→    renameAgent,
858→    clearHistory,
859→    tasks,
860→    createTask,
861→    updateTask,
862→    deleteTask,
863→    delegateTask,
864→    workspaces,
865→    activeWorkspaceId,
866→    setActiveWorkspaceId,
867→    createWorkspace,
868→    renameWorkspace,
869→    deleteWorkspace,
870→    browseDirectory,
871→    directoryListing,
872→  };
873→}
874→

