   1→/**
   2→ * Standalone WebSocket relay server for the thos dashboard.
   3→ *
   4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
   5→ * `dev` script). It cannot be a Next.js API route because API routes don't
   6→ * support persistent WebSocket connections.
   7→ *
   8→ * ## Architecture
   9→ *
  10→ * Two WebSocket path families:
  11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
  12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
  13→ *
  14→ * The server supports multiple concurrent agents, each tracked in the
  15→ * `agents` Map keyed by a short random ID.
  16→ *
  17→ * ## Connection flow (browser)
  18→ *
  19→ * On browser connect, the server sends two small messages:
  20→ * 1. `agent_list`  — metadata for all agents (sidebar).
  21→ * 2. `task_list`   — all tasks.
  22→ *
  23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
  24→ * browser sends `{ type: "request_history", agentId }` when the user
  25→ * selects an agent, and the server responds with `message_history` for
  26→ * that single agent. This avoids sending megabytes of JSON on connect,
  27→ * which caused multi-minute loading times on mobile networks.
  28→ *
  29→ * Live messages for active agents are still broadcast to all browsers
  30→ * via `relay` messages in real time.
  31→ *
  32→ * ## Message flow (spawning)
  33→ *
  34→ * 1. Browser sends `{ type: "spawn", prompt }`.
  35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
  36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
  37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
  38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
  39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
  40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
  41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
  42→ *
  43→ * ## Resilience features
  44→ *
  45→ * - **Server-side message history** — every relay message is stored per-agent.
  46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
  47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
  48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
  49→ *   can reconnect to the new server if they retry their WebSocket connection.
  50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
  51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
  52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
  53→ */
  54→import { WebSocketServer, WebSocket } from "ws";
  55→import { execSync, spawn } from "child_process";
  56→import { randomBytes } from "crypto";
  57→import type { IncomingMessage } from "http";
  58→import { readdirSync, statSync, existsSync } from "fs";
  59→import { join, dirname, basename } from "path";
  60→import type {
  61→  BrowserMessage,
  62→  ClaudeMessage,
  63→  ServerMessage,
  64→  AgentStatus,
  65→  AgentInfo,
  66→  Task,
  67→  Workspace,
  68→  DirectoryEntry,
  69→} from "../lib/types";
  70→import { SessionStore, type PersistedAgent } from "./session-store";
  71→import { TaskStore } from "./task-store";
  72→import { WorkspaceStore } from "./workspace-store";
  73→
  74→const PORT = 9900;
  75→const TMUX_SESSION_PREFIX = "thos-agent";
  76→
  77→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
  78→function isAllowedIP(ip: string | undefined): boolean {
  79→  if (!ip) return false;
  80→  // Strip IPv6-mapped IPv4 prefix
  81→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
  82→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
  83→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
  84→  const parts = addr.split(".");
  85→  if (parts.length !== 4) return false;
  86→  const first = parseInt(parts[0], 10);
  87→  const second = parseInt(parts[1], 10);
  88→  return first === 100 && second >= 64 && second <= 127;
  89→}
  90→
  91→const wss = new WebSocketServer({
  92→  port: PORT,
  93→  verifyClient: (info: { req: { socket: { remoteAddress?: string } } }) => {
  94→    const ip = info.req.socket.remoteAddress;
  95→    const allowed = isAllowedIP(ip);
  96→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
  97→    return allowed;
  98→  },
  99→});
 100→const store = new SessionStore();
 101→
 102→// ── Multi-agent state ──────────────────────────────────────────────────────
 103→
 104→interface AgentState {
 105→  agentId: string;
 106→  claudeSocket: WebSocket | null;
 107→  tmuxSession: string | null;
 108→  pendingPrompt: string | null;
 109→  status: AgentStatus;
 110→  label: string;
 111→  createdAt: number;
 112→  /** Captured from system/init, used in subsequent user messages. */
 113→  sessionId: string | null;
 114→  /** Workspace this agent belongs to. */
 115→  workspaceId: string | null;
 116→  /** Model name from system/init or requested at spawn time. */
 117→  model: string | null;
 118→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 119→  pendingControlRequests: Map<string, Record<string, unknown>>;
 120→  /** All messages sent to the browser for this agent (source of truth). */
 121→  messageHistory: ServerMessage[];
 122→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 123→  pendingMessages: string[];
 124→}
 125→
 126→const agents = new Map<string, AgentState>();
 127→const taskStore = new TaskStore();
 128→const tasks = new Map<string, Task>();
 129→const workspaceStore = new WorkspaceStore();
 130→const workspaces = new Map<string, Workspace>();
 131→
 132→/** All active browser connections (supports multiple tabs). */
 133→const browserSockets = new Set<WebSocket>();
 134→
 135→/** Per-browser workspace scope (null = show all). */
 136→const browserWorkspaceScope = new Map<WebSocket, string | null>();
 137→
 138→/** Generate a short random agent ID. */
 139→function newAgentId(): string {
 140→  return randomBytes(4).toString("hex");
 141→}
 142→
 143→// ── tmux helpers ───────────────────────────────────────────────────────────
 144→
 145→/** Return the set of currently alive tmux session names matching the thos prefix. */
 146→function listAliveTmuxSessions(): Set<string> {
 147→  try {
 148→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
 149→      encoding: "utf-8",
 150→    }).trim();
 151→    if (!output) return new Set();
 152→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
 153→  } catch {
 154→    return new Set();
 155→  }
 156→}
 157→
 158→// ── Persistence helpers ────────────────────────────────────────────────────
 159→
 160→/** Build a PersistedAgent snapshot from live state. */
 161→function toPersistedAgent(agent: AgentState): PersistedAgent {
 162→  return {
 163→    id: agent.agentId,
 164→    state: {
 165→      agentId: agent.agentId,
 166→      status: agent.status,
 167→      tmuxSession: agent.tmuxSession,
 168→      label: agent.label,
 169→      createdAt: agent.createdAt,
 170→      sessionId: agent.sessionId,
 171→      workspaceId: agent.workspaceId,
 172→      model: agent.model,
 173→    },
 174→    messageHistory: agent.messageHistory,
 175→  };
 176→}
 177→
 178→/**
 179→ * Compact a message history by deduplicating cumulative snapshots.
 180→ * Keeps only the last version of each assistant/user message ID.
 181→ * Called on restore to shrink legacy bloated histories.
 182→ */
 183→function compactHistory(history: ServerMessage[]): ServerMessage[] {
 184→  // Build a map of msgId → last index
 185→  const lastIndex = new Map<string, number>();
 186→  for (let i = 0; i < history.length; i++) {
 187→    const id = getRelayMessageId(history[i]);
 188→    if (id) lastIndex.set(id, i);
 189→  }
 190→  // Keep only messages that are either non-deduplicable or the last occurrence
 191→  return history.filter((msg, i) => {
 192→    const id = getRelayMessageId(msg);
 193→    if (!id) return true; // non-relay or no message ID — always keep
 194→    return lastIndex.get(id) === i;
 195→  });
 196→}
 197→
 198→/** Persist agent state (debounced — use for streaming events). */
 199→function persistAgent(agent: AgentState) {
 200→  store.save(toPersistedAgent(agent));
 201→}
 202→
 203→/** Persist agent state immediately (use for critical state changes). */
 204→function persistAgentSync(agent: AgentState) {
 205→  store.saveSync(toPersistedAgent(agent));
 206→}
 207→
 208→// ── Restore from disk on startup ───────────────────────────────────────────
 209→
 210→function restoreAgents() {
 211→  const persisted = store.loadAll();
 212→  const aliveSessions = listAliveTmuxSessions();
 213→
 214→  for (const p of persisted) {
 215→    const agent: AgentState = {
 216→      agentId: p.state.agentId,
 217→      claudeSocket: null,
 218→      tmuxSession: p.state.tmuxSession,
 219→      pendingPrompt: null,
 220→      status: p.state.status,
 221→      label: p.state.label,
 222→      createdAt: p.state.createdAt,
 223→      sessionId: p.state.sessionId,
 224→      workspaceId: p.state.workspaceId ?? null,
 225→      model: p.state.model ?? null,
 226→      pendingControlRequests: new Map(),
 227→      messageHistory: compactHistory(p.messageHistory),
 228→      pendingMessages: [],
 229→    };
 230→
 231→    // Determine status for agents that were active when the server last ran
 232→    if (agent.status !== "done" && agent.status !== "error") {
 233→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
 234→      if (tmuxAlive) {
 235→        // tmux session still alive — CLI may reconnect to this server
 236→        agent.status = "disconnected";
 237→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
 238→      } else {
 239→        // tmux session gone — agent is archived
 240→        agent.status = "done";
 241→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
 242→      }
 243→    }
 244→
 245→    agents.set(agent.agentId, agent);
 246→    const originalCount = p.messageHistory.length;
 247→    const compactedCount = agent.messageHistory.length;
 248→    const saved = originalCount - compactedCount;
 249→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
 250→
 251→    // Persist compacted history back to disk
 252→    if (saved > 0) {
 253→      persistAgentSync(agent);
 254→    }
 255→  }
 256→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
 257→}
 258→
 259→restoreAgents();
 260→
 261→// ── Task restore + helpers ────────────────────────────────────────────────
 262→
 263→function restoreTasks() {
 264→  const persisted = taskStore.loadAll();
 265→  for (const t of persisted) {
 266→    tasks.set(t.id, t);
 267→  }
 268→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
 269→}
 270→
 271→restoreTasks();
 272→
 273→// ── Workspace restore + helpers ──────────────────────────────────────────
 274→
 275→function restoreWorkspaces() {
 276→  const persisted = workspaceStore.loadAll();
 277→  for (const w of persisted) {
 278→    workspaces.set(w.id, w);
 279→  }
 280→  console.log(`[restore] loaded ${persisted.length} workspaces from disk`);
 281→}
 282→
 283→restoreWorkspaces();
 284→
 285→/** Persist all workspaces to disk (sync). */
 286→function persistWorkspaces() {
 287→  workspaceStore.saveSync(Array.from(workspaces.values()));
 288→}
 289→
 290→/** Send the full workspace list to all browsers. */
 291→function broadcastWorkspaceList() {
 292→  const payload = JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) });
 293→  for (const ws of browserSockets) {
 294→    if (ws.readyState === WebSocket.OPEN) {
 295→      ws.send(payload);
 296→    }
 297→  }
 298→}
 299→
 300→/** Build the full task list sorted by creation time (newest first), optionally filtered by workspace. */
 301→function buildTaskList(workspaceId?: string | null): Task[] {
 302→  let list = Array.from(tasks.values());
 303→  if (workspaceId !== undefined && workspaceId !== null) {
 304→    list = list.filter((t) => t.workspaceId === workspaceId);
 305→  }
 306→  return list.sort((a, b) => b.createdAt - a.createdAt);
 307→}
 308→
 309→/** Send the full task list to all browsers (scoped per-browser workspace). */
 310→function broadcastTaskList() {
 311→  for (const ws of browserSockets) {
 312→    if (ws.readyState !== WebSocket.OPEN) continue;
 313→    const scope = browserWorkspaceScope.get(ws) ?? null;
 314→    ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 315→  }
 316→}
 317→
 318→/** Persist all tasks to disk (sync). */
 319→function persistTasks() {
 320→  taskStore.saveSync(Array.from(tasks.values()));
 321→}
 322→
 323→// ── Helpers ────────────────────────────────────────────────────────────────
 324→
 325→/** Send a JSON message to all connected browsers. */
 326→function sendToBrowser(msg: ServerMessage) {
 327→  const payload = JSON.stringify(msg);
 328→  for (const ws of browserSockets) {
 329→    if (ws.readyState === WebSocket.OPEN) {
 330→      ws.send(payload);
 331→    }
 332→  }
 333→}
 334→
 335→/** Build a snapshot of all agents for the sidebar, optionally filtered by workspace. */
 336→function buildAgentList(workspaceId?: string | null): AgentInfo[] {
 337→  let list = Array.from(agents.values());
 338→  if (workspaceId !== undefined && workspaceId !== null) {
 339→    list = list.filter((a) => a.workspaceId === workspaceId);
 340→  }
 341→  return list.map((a) => ({
 342→    agentId: a.agentId,
 343→    status: a.status,
 344→    tmuxSession: a.tmuxSession,
 345→    label: a.label,
 346→    createdAt: a.createdAt,
 347→    workspaceId: a.workspaceId,
 348→    model: a.model,
 349→  }));
 350→}
 351→
 352→/** Send the full agent list to all browsers (scoped per-browser workspace). */
 353→function broadcastAgentList() {
 354→  for (const ws of browserSockets) {
 355→    if (ws.readyState !== WebSocket.OPEN) continue;
 356→    const scope = browserWorkspaceScope.get(ws) ?? null;
 357→    ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 358→  }
 359→}
 360→
 361→/** Update an agent's status, notify browsers, broadcast list, and persist. */
 362→function setAgentStatus(agentId: string, status: AgentStatus) {
 363→  const agent = agents.get(agentId);
 364→  if (!agent) return;
 365→  agent.status = status;
 366→  sendToBrowser({ type: "status", agentId, status });
 367→  broadcastAgentList();
 368→  persistAgentSync(agent);
 369→}
 370→
 371→/**
 372→ * Extract a stable dedup key from a relay message, if present.
 373→ *
 374→ * Claude NDJSON sends cumulative snapshots for two message types:
 375→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 376→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 377→ *
 378→ * Additionally, one-per-session messages are deduplicated by session_id:
 379→ * - `system/init` — keyed by `init:<session_id>`
 380→ * - `result` — keyed by `result:<session_id>`
 381→ *
 382→ * We deduplicate by replacing the previous snapshot in `messageHistory`
 383→ * instead of appending, reducing storage from O(n²) to O(n).
 384→ */
 385→function getRelayMessageId(msg: ServerMessage): string | null {
 386→  if (msg.type !== "relay") return null;
 387→  const inner = msg.message;
 388→  if (inner.type === "assistant") {
 389→    return (inner as { message?: { id?: string } }).message?.id ?? null;
 390→  }
 391→  if (inner.type === "user") {
 392→    return (inner as { uuid?: string }).uuid ?? null;
 393→  }
 394→  // Dedup system/init and result by session_id so they don't stack on reload
 395→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
 396→    const sid = (inner as { session_id?: string }).session_id;
 397→    return sid ? `init:${sid}` : null;
 398→  }
 399→  if (inner.type === "result") {
 400→    const sid = (inner as { session_id?: string }).session_id;
 401→    return sid ? `result:${sid}` : null;
 402→  }
 403→  return null;
 404→}
 405→
 406→/**
 407→ * Record a message in the agent's history and send to all browsers.
 408→ *
 409→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
 410→ * previous snapshot with the same message ID instead of appending. This keeps
 411→ * only the final version of each message, dramatically reducing file sizes
 412→ * (e.g. 38 MB → ~1 MB for a typical session).
 413→ */
 414→function recordAndSend(agentId: string, msg: ServerMessage) {
 415→  const agent = agents.get(agentId);
 416→  if (agent) {
 417→    const msgId = getRelayMessageId(msg);
 418→    if (msgId) {
 419→      // Replace previous snapshot with same message ID (search from end for speed)
 420→      let replaced = false;
 421→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
 422→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
 423→          agent.messageHistory[i] = msg;
 424→          replaced = true;
 425→          break;
 426→        }
 427→      }
 428→      if (!replaced) {
 429→        agent.messageHistory.push(msg);
 430→      }
 431→    } else {
 432→      agent.messageHistory.push(msg);
 433→    }
 434→    persistAgent(agent); // debounced — streaming messages come fast
 435→  }
 436→  sendToBrowser(msg);
 437→}
 438→
 439→// ── Agent lifecycle ────────────────────────────────────────────────────────
 440→
 441→/**
 442→ * Stop a running agent by killing its tmux session and closing the CLI socket.
 443→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
 444→ */
 445→function stopAgent(agentId: string) {
 446→  const agent = agents.get(agentId);
 447→  if (!agent) return;
 448→
 449→  if (agent.tmuxSession) {
 450→    try {
 451→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 452→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
 453→    } catch {
 454→      // Session may already be dead
 455→    }
 456→  }
 457→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 458→    agent.claudeSocket.close();
 459→  }
 460→  agent.claudeSocket = null;
 461→  setAgentStatus(agentId, "done");
 462→}
 463→
 464→/**
 465→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
 466→ */
 467→function deleteAgent(agentId: string) {
 468→  const agent = agents.get(agentId);
 469→  if (!agent) return;
 470→
 471→  if (agent.tmuxSession) {
 472→    try {
 473→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 474→    } catch {}
 475→  }
 476→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 477→    agent.claudeSocket.close();
 478→  }
 479→  agents.delete(agentId);
 480→  store.remove(agentId);
 481→  broadcastAgentList();
 482→}
 483→
 484→/**
 485→ * Spawn a new Claude CLI process inside a tmux session.
 486→ *
 487→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
 488→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
 489→ * If `workspaceId` is provided, the tmux session starts in that workspace's cwd.
 490→ */
 491→function spawnClaude(prompt: string, workspaceId?: string | null, model?: string | null): string {
 492→  const agentId = newAgentId();
 493→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
 494→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
 495→
 496→  const agent: AgentState = {
 497→    agentId,
 498→    claudeSocket: null,
 499→    tmuxSession: null,
 500→    pendingPrompt: prompt,
 501→    status: "spawning",
 502→    label,
 503→    createdAt: Date.now(),
 504→    sessionId: null,
 505→    workspaceId: workspaceId ?? null,
 506→    model: model ?? null,
 507→    pendingControlRequests: new Map(),
 508→    messageHistory: [],
 509→    pendingMessages: [],
 510→  };
 511→  agents.set(agentId, agent);
 512→
 513→  // Notify browsers
 514→  sendToBrowser({ type: "spawned", agentId });
 515→  broadcastAgentList();
 516→  persistAgentSync(agent);
 517→
 518→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
 519→  // tmux new-session runs detached (-d) so spawn() returns immediately.
 520→  const modelFlag = model ? ` --model ${model}` : "";
 521→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions${modelFlag} --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
 522→
 523→  // If the agent belongs to a workspace, start tmux in that workspace's cwd
 524→  const workspace = workspaceId ? workspaces.get(workspaceId) : null;
 525→  const tmuxArgs = ["new-session", "-d", "-s", sessionName];
 526→  if (workspace) {
 527→    tmuxArgs.push("-c", workspace.cwd);
 528→  }
 529→  tmuxArgs.push("bash", "-c", claudeCmd);
 530→
 531→  const tmux = spawn("tmux", tmuxArgs, {
 532→    stdio: "ignore",
 533→  });
 534→
 535→  tmux.on("error", (err) => {
 536→    console.error("[tmux spawn error]", err);
 537→    setAgentStatus(agentId, "error");
 538→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
 539→  });
 540→
 541→  tmux.on("exit", (code) => {
 542→    if (code !== 0) {
 543→      console.error(`[tmux] new-session exited with code ${code}`);
 544→      setAgentStatus(agentId, "error");
 545→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
 546→      return;
 547→    }
 548→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
 549→    agent.tmuxSession = sessionName;
 550→    broadcastAgentList();
 551→    persistAgentSync(agent);
 552→  });
 553→
 554→  return agentId;
 555→}
 556→
 557→// ── Message handlers ───────────────────────────────────────────────────────
 558→
 559→/**
 560→ * Process an incoming NDJSON message from a specific Claude CLI.
 561→ *
 562→ * Status flow matches the Companion protocol:
 563→ * - hook_response → send pending prompt → "thinking"
 564→ * - system/init   → "connected" + capture session_id
 565→ * - assistant      → "thinking"
 566→ * - result         → "connected" (CLI stays alive for multi-turn)
 567→ * - CLI disconnect → "done" (handled in connection close handler)
 568→ */
 569→function handleClaudeMessage(agentId: string, raw: string) {
 570→  const agent = agents.get(agentId);
 571→  if (!agent) return;
 572→
 573→  let msg: ClaudeMessage;
 574→  try {
 575→    msg = JSON.parse(raw);
 576→  } catch {
 577→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
 578→    return;
 579→  }
 580→
 581→  // Silently ignore keep_alive messages
 582→  if (msg.type === "keep_alive") return;
 583→
 584→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
 585→
 586→  // After hook_response, send the pending prompt
 587→  if (
 588→    msg.type === "system" &&
 589→    (msg as { subtype?: string }).subtype === "hook_response" &&
 590→    agent.pendingPrompt &&
 591→    agent.claudeSocket?.readyState === WebSocket.OPEN
 592→  ) {
 593→    const promptContent = agent.pendingPrompt;
 594→    const userMsg = JSON.stringify({
 595→      type: "user",
 596→      message: { role: "user", content: promptContent },
 597→      parent_tool_use_id: null,
 598→      session_id: agent.sessionId ?? "",
 599→    });
 600→    console.log(`[server → claude:${agentId}]`, userMsg);
 601→    agent.claudeSocket.send(userMsg + "\n");
 602→    agent.pendingPrompt = null;
 603→    setAgentStatus(agentId, "thinking");
 604→
 605→    // Record the initial user message so it appears in chat and persists across reloads
 606→    recordAndSend(agentId, {
 607→      type: "relay",
 608→      agentId,
 609→      message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
 610→    });
 611→  }
 612→
 613→  // Track status based on message type
 614→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 615→    // Capture session_id and model for subsequent user messages
 616→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
 617→    agent.model = (msg as { model?: string }).model ?? agent.model;
 618→    setAgentStatus(agentId, "connected");
 619→  } else if (msg.type === "assistant") {
 620→    setAgentStatus(agentId, "thinking");
 621→  } else if (msg.type === "result") {
 622→    // CLI stays alive after result — ready for the next turn.
 623→    // Status only goes to "done" when the CLI WebSocket actually closes.
 624→    setAgentStatus(agentId, "connected");
 625→  }
 626→
 627→  // Store control_request inputs for building proper responses later
 628→  if (msg.type === "control_request") {
 629→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
 630→    if (cr.request_id && cr.request?.input) {
 631→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
 632→    }
 633→  }
 634→
 635→  // Record in history and relay to browsers
 636→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
 637→}
 638→
 639→/**
 640→ * Process an incoming JSON message from the browser.
 641→ * - `spawn`: create a new agent (does NOT kill others).
 642→ * - `send_message`: forward a follow-up user message to the specified agent.
 643→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
 644→ * - `kill_agent`: stop the CLI and tmux session.
 645→ * - `delete_agent`: permanently remove an agent.
 646→ * - `rename_agent`: update an agent's label.
 647→ * - `clear_history`: wipe an agent's message history.
 648→ * - `request_history`: send message history for a single agent (lazy loading).
 649→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
 650→ */
 651→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
 652→  let msg: BrowserMessage;
 653→  try {
 654→    msg = JSON.parse(raw);
 655→  } catch {
 656→    console.error("[browser] invalid JSON:", raw);
 657→    return;
 658→  }
 659→
 660→  console.log("[browser →]", msg.type);
 661→
 662→  switch (msg.type) {
 663→    case "spawn": {
 664→      const scope = browserWorkspaceScope.get(senderWs) ?? msg.workspaceId ?? null;
 665→      spawnClaude(msg.prompt, scope, msg.model);
 666→      break;
 667→    }
 668→
 669→    case "send_message": {
 670→      const agent = agents.get(msg.agentId);
 671→      if (!agent) {
 672→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
 673→        break;
 674→      }
 675→
 676→      // Record the user message in history so it persists across reloads.
 677→      // Do NOT broadcast — the sending browser already has it optimistically,
 678→      // and other browsers will get it when they request_history.
 679→      agent.messageHistory.push({
 680→        type: "relay",
 681→        agentId: msg.agentId,
 682→        message: { type: "user", message: { role: "user", content: msg.content } },
 683→      } as ServerMessage);
 684→      persistAgent(agent);
 685→
 686→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 687→        const userMsg = JSON.stringify({
 688→          type: "user",
 689→          message: { role: "user", content: msg.content },
 690→          parent_tool_use_id: null,
 691→          session_id: agent.sessionId ?? "",
 692→        });
 693→        agent.claudeSocket.send(userMsg + "\n");
 694→        setAgentStatus(msg.agentId, "thinking");
 695→      } else {
 696→        // Queue message for delivery when CLI reconnects
 697→        const userMsg = JSON.stringify({
 698→          type: "user",
 699→          message: { role: "user", content: msg.content },
 700→          parent_tool_use_id: null,
 701→          session_id: agent.sessionId ?? "",
 702→        });
 703→        agent.pendingMessages.push(userMsg);
 704→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
 705→        persistAgentSync(agent);
 706→      }
 707→      break;
 708→    }
 709→
 710→    case "control_response": {
 711→      const agent = agents.get(msg.agentId);
 712→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
 713→        // Retrieve the original tool input to include as updatedInput (required by protocol)
 714→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
 715→        agent.pendingControlRequests.delete(msg.request_id);
 716→
 717→        // If the browser sent answers (from AskUserQuestion), merge them into the input
 718→        const answers = (msg as { answers?: Record<string, string> }).answers;
 719→        const updatedInput = answers
 720→          ? { ...originalInput, answers }
 721→          : originalInput;
 722→
 723→        const response = JSON.stringify({
 724→          type: "control_response",
 725→          response: {
 726→            subtype: "success",
 727→            request_id: msg.request_id,
 728→            response: msg.allow
 729→              ? { behavior: "allow", updatedInput }
 730→              : { behavior: "deny", message: "Denied by user" },
 731→          },
 732→        });
 733→        agent.claudeSocket.send(response + "\n");
 734→      }
 735→      break;
 736→    }
 737→
 738→    case "kill_agent":
 739→      stopAgent(msg.agentId);
 740→      break;
 741→
 742→    case "delete_agent":
 743→      deleteAgent(msg.agentId);
 744→      break;
 745→
 746→    case "rename_agent": {
 747→      const agent = agents.get(msg.agentId);
 748→      if (!agent) break;
 749→      agent.label = msg.label;
 750→      broadcastAgentList();
 751→      persistAgentSync(agent);
 752→      break;
 753→    }
 754→
 755→    case "clear_history": {
 756→      const agent = agents.get(msg.agentId);
 757→      if (!agent) break;
 758→      agent.messageHistory = [];
 759→      persistAgentSync(agent);
 760→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
 761→      break;
 762→    }
 763→
 764→    case "request_history": {
 765→      console.log(`[browser] request_history for ${msg.agentId}`);
 766→      sendHistoryToSocket(senderWs, msg.agentId);
 767→      break;
 768→    }
 769→
 770→    case "create_task": {
 771→      const taskId = randomBytes(4).toString("hex");
 772→      const task: Task = {
 773→        id: taskId,
 774→        title: msg.title,
 775→        description: msg.description,
 776→        status: "todo",
 777→        priority: msg.priority,
 778→        agentId: null,
 779→        workspaceId: browserWorkspaceScope.get(senderWs) ?? null,
 780→        createdAt: Date.now(),
 781→        updatedAt: Date.now(),
 782→      };
 783→      tasks.set(taskId, task);
 784→      persistTasks();
 785→      broadcastTaskList();
 786→      break;
 787→    }
 788→
 789→    case "update_task": {
 790→      const task = tasks.get(msg.taskId);
 791→      if (!task) break;
 792→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
 793→      persistTasks();
 794→      broadcastTaskList();
 795→
 796→      // Archive the linked agent when a task is marked as done
 797→      if (task.status === "done" && task.agentId) {
 798→        const linkedAgent = agents.get(task.agentId);
 799→        if (linkedAgent && linkedAgent.status !== "done") {
 800→          stopAgent(task.agentId);
 801→        }
 802→      }
 803→      break;
 804→    }
 805→
 806→    case "delete_task": {
 807→      tasks.delete(msg.taskId);
 808→      persistTasks();
 809→      broadcastTaskList();
 810→      break;
 811→    }
 812→
 813→    case "delegate_task": {
 814→      const task = tasks.get(msg.taskId);
 815→      if (!task) break;
 816→      const prompt = `Task: ${task.title}\n\n${task.description}`;
 817→      const agentId = spawnClaude(prompt, task.workspaceId);
 818→      task.agentId = agentId;
 819→      task.status = "in-progress";
 820→      task.updatedAt = Date.now();
 821→      persistTasks();
 822→      broadcastTaskList();
 823→      break;
 824→    }
 825→
 826→    // ── Workspace messages ──────────────────────────────────────────────
 827→
 828→    case "set_workspace": {
 829→      browserWorkspaceScope.set(senderWs, msg.workspaceId);
 830→      // Re-send scoped agent list and task list to this browser
 831→      const scope = msg.workspaceId;
 832→      senderWs.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 833→      senderWs.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 834→      break;
 835→    }
 836→
 837→    case "create_workspace": {
 838→      const id = randomBytes(4).toString("hex");
 839→      const workspace: Workspace = {
 840→        id,
 841→        name: msg.name,
 842→        cwd: msg.cwd,
 843→        createdAt: Date.now(),
 844→      };
 845→      workspaces.set(id, workspace);
 846→      persistWorkspaces();
 847→      broadcastWorkspaceList();
 848→      break;
 849→    }
 850→
 851→    case "rename_workspace": {
 852→      const workspace = workspaces.get(msg.workspaceId);
 853→      if (!workspace) break;
 854→      workspace.name = msg.name;
 855→      persistWorkspaces();
 856→      broadcastWorkspaceList();
 857→      break;
 858→    }
 859→
 860→    case "delete_workspace": {
 861→      workspaces.delete(msg.workspaceId);
 862→      // Unlink agents and tasks from the deleted workspace
 863→      for (const agent of agents.values()) {
 864→        if (agent.workspaceId === msg.workspaceId) {
 865→          agent.workspaceId = null;
 866→          persistAgentSync(agent);
 867→        }
 868→      }
 869→      for (const task of tasks.values()) {
 870→        if (task.workspaceId === msg.workspaceId) {
 871→          task.workspaceId = null;
 872→        }
 873→      }
 874→      persistTasks();
 875→      persistWorkspaces();
 876→      broadcastWorkspaceList();
 877→      broadcastAgentList();
 878→      broadcastTaskList();
 879→      break;
 880→    }
 881→
 882→    case "browse_directory": {
 883→      const dirPath = msg.path;
 884→      try {
 885→        if (!existsSync(dirPath)) {
 886→          senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 887→          break;
 888→        }
 889→        const entries: DirectoryEntry[] = [];
 890→        // Add parent directory entry
 891→        const parent = dirname(dirPath);
 892→        if (parent !== dirPath) {
 893→          entries.push({ name: "..", path: parent });
 894→        }
 895→        // List subdirectories only
 896→        const items = readdirSync(dirPath);
 897→        for (const item of items) {
 898→          if (item.startsWith(".")) continue; // skip dotfiles
 899→          const fullPath = join(dirPath, item);
 900→          try {
 901→            const stat = statSync(fullPath);
 902→            if (stat.isDirectory()) {
 903→              entries.push({ name: item, path: fullPath });
 904→            }
 905→          } catch {
 906→            // skip inaccessible entries
 907→          }
 908→        }
 909→        // Sort: ".." first, then alphabetical
 910→        entries.sort((a, b) => {
 911→          if (a.name === "..") return -1;
 912→          if (b.name === "..") return 1;
 913→          return a.name.localeCompare(b.name);
 914→        });
 915→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries }));
 916→      } catch (err) {
 917→        console.error(`[browse_directory] error reading ${dirPath}:`, err);
 918→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 919→      }
 920→      break;
 921→    }
 922→  }
 923→}
 924→
 925→// ── Send message history to a single browser socket ────────────────────────
 926→
 927→/** Send initial state (workspaces, agent list, tasks) to a newly connected browser. */
 928→function sendFullStateToSocket(ws: WebSocket) {
 929→  if (ws.readyState !== WebSocket.OPEN) return;
 930→
 931→  // Workspace list
 932→  ws.send(JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) }));
 933→
 934→  // Agent list (sidebar metadata) — scoped if browser has a workspace set
 935→  const scope = browserWorkspaceScope.get(ws) ?? null;
 936→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 937→
 938→  // Task list — scoped if browser has a workspace set
 939→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 940→}
 941→
 942→/** Send message history for a single agent to a specific browser socket. */
 943→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
 944→  const agent = agents.get(agentId);
 945→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
 946→  ws.send(
 947→    JSON.stringify({
 948→      type: "message_history",
 949→      agentId: agent.agentId,
 950→      messages: agent.messageHistory,
 951→    })
 952→  );
 953→}
 954→
 955→// ── Connection handler — route by URL path ────────────────────────────────
 956→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
 957→  const path = req.url ?? "/";
 958→  console.log(`[ws connected] path=${path}`);
 959→
 960→  if (path === "/browser") {
 961→    // Send full state BEFORE adding to browserSockets so that live
 962→    // relay broadcasts don't interleave with the history replay.
 963→    sendFullStateToSocket(ws);
 964→    browserSockets.add(ws);
 965→
 966→    ws.on("message", (data) => {
 967→      handleBrowserMessage(data.toString(), ws);
 968→    });
 969→
 970→    ws.on("close", () => {
 971→      console.log("[browser disconnected]");
 972→      browserSockets.delete(ws);
 973→      browserWorkspaceScope.delete(ws);
 974→      // Do NOT kill agents — keep them alive for reconnect
 975→    });
 976→  } else if (path.startsWith("/claude/")) {
 977→    // Parse agentId from /claude/<agentId>
 978→    const agentId = path.slice("/claude/".length);
 979→    const agent = agents.get(agentId);
 980→
 981→    if (!agent) {
 982→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
 983→      ws.close();
 984→      return;
 985→    }
 986→
 987→    agent.claudeSocket = ws;
 988→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
 989→
 990→    // Notify browsers that CLI is connected
 991→    sendToBrowser({ type: "cli_connected", agentId });
 992→
 993→    // Flush any pending messages queued while CLI was disconnected
 994→    if (agent.pendingMessages.length > 0) {
 995→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
 996→      for (const queued of agent.pendingMessages) {
 997→        ws.send(queued + "\n");
 998→      }
 999→      agent.pendingMessages = [];
1000→      persistAgentSync(agent);
1001→    }
1002→
1003→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
1004→    // server to send the first user message rather than emitting
1005→    // hook_started/hook_response on connect.
1006→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
1007→      const promptContent = agent.pendingPrompt;
1008→      const userMsg = JSON.stringify({
1009→        type: "user",
1010→        message: { role: "user", content: promptContent },
1011→        parent_tool_use_id: null,
1012→        session_id: agent.sessionId ?? "",
1013→      });
1014→      console.log(`[server → claude:${agentId}] sending pending prompt`);
1015→      ws.send(userMsg + "\n");
1016→      agent.pendingPrompt = null;
1017→      setAgentStatus(agentId, "thinking");
1018→
1019→      // Record the initial user message so it appears in chat and persists across reloads
1020→      recordAndSend(agentId, {
1021→        type: "relay",
1022→        agentId,
1023→        message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
1024→      });
1025→    }
1026→
1027→    ws.on("message", (data) => {
1028→      handleClaudeMessage(agentId, data.toString());
1029→    });
1030→
1031→    ws.on("close", () => {
1032→      console.log(`[claude:${agentId} CLI disconnected]`);
1033→      if (agent.claudeSocket === ws) {
1034→        agent.claudeSocket = null;
1035→        if (agent.status !== "error") {
1036→          setAgentStatus(agentId, "done");
1037→          sendToBrowser({ type: "cli_disconnected", agentId });
1038→
1039→          // Auto-complete any task linked to this agent
1040→          for (const task of tasks.values()) {
1041→            if (task.agentId === agentId && task.status !== "done") {
1042→              task.status = "done";
1043→              task.updatedAt = Date.now();
1044→              persistTasks();
1045→              broadcastTaskList();
1046→              break;
1047→            }
1048→          }
1049→        }
1050→      }
1051→    });
1052→  } else {
1053→    console.log(`[ws] unknown path: ${path}, closing`);
1054→    ws.close();
1055→  }
1056→});
1057→
1058→// ── Graceful shutdown ─────────────────────────────────────────────────────
1059→
1060→function shutdown() {
1061→  console.log("[ws server] shutting down...");
1062→
1063→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
1064→  // so CLI processes can reconnect if the server restarts.
1065→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
1066→  store.flushAll(allPersisted);
1067→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
1068→
1069→  taskStore.flush(Array.from(tasks.values()));
1070→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
1071→
1072→  persistWorkspaces();
1073→  console.log(`[ws server] saved ${workspaces.size} workspaces to disk`);
1074→
1075→  wss.close();
1076→  process.exit(0);
1077→}
1078→
1079→process.on("SIGTERM", shutdown);
1080→process.on("SIGINT", shutdown);
1081→
1082→console.log(`[ws server] listening on port ${PORT}`);
1083→

