"use client";

/**
 * Sidebar listing all agents with status dots, truncated labels,
 * tmux session names, and a "+" button to spawn a new agent.
 *
 * Split into two sections:
 * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
 * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 *
 * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 * Rename swaps the label for an inline input.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { EllipsisVertical, Pin, Plus } from "lucide-react";
import type { AgentStatus, Workspace } from "@/lib/types";
import type { AgentClientState } from "@/hooks/use-websocket";
import { cn } from "@/lib/utils";
import { WorkspaceSwitcher } from "./workspace-switcher";

/** Status dot color + optional pulse animation. */
const STATUS_DOT: Record<AgentStatus, string> = {
  idle: "bg-muted-foreground",
  spawning: "bg-yellow-500 animate-pulse",
  connected: "bg-green-500",
  thinking: "bg-blue-500 animate-pulse",
  done: "bg-muted-foreground",
  disconnected: "bg-orange-500 animate-pulse",
  error: "bg-red-500",
};

/** Statuses where the CLI is actively running and can be killed. */
const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
/** Statuses considered archived (session ended, read-only). */
const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);

interface ContextMenuState {
  agentId: string;
  x: number;
  y: number;
}

export function AgentSidebar({
  agents,
  agentOrder,
  activeAgentId,
  loading,
  onSelect,
  onNewAgent,
  onKill,
  onDelete,
  onRename,
  onClearHistory,
  onPin,
  workspaces,
  activeWorkspaceId,
  onSelectWorkspace,
  onRenameWorkspace,
  onDeleteWorkspace,
  onOpenFolder,
}: {
  agents: Map<string, AgentClientState>;
  agentOrder: string[];
  activeAgentId: string | null;
  loading?: boolean;
  onSelect: (agentId: string | null) => void;
  onNewAgent: () => void;
  onKill: (agentId: string) => void;
  onDelete: (agentId: string) => void;
  onRename: (agentId: string, label: string) => void;
  onClearHistory: (agentId: string) => void;
  onPin: (agentId: string, pinned: boolean) => void;
  workspaces: Workspace[];
  activeWorkspaceId: string | null;
  onSelectWorkspace: (workspaceId: string | null) => void;
  onRenameWorkspace: (workspaceId: string, name: string) => void;
  onDeleteWorkspace: (workspaceId: string) => void;
  onOpenFolder: () => void;
}) {
  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  // Sort helper: most recent first by createdAt
  const byRecency = (a: string, b: string) => {
    const ca = agents.get(a)?.createdAt ?? 0;
    const cb = agents.get(b)?.createdAt ?? 0;
    return cb - ca;
  };

  // Split agents into pinned, active (non-pinned, non-archived), and archived
  const pinnedIds = agentOrder
    .filter((id) => {
      const a = agents.get(id);
      return a && a.pinned;
    })
    .sort(byRecency);
  const activeIds = agentOrder
    .filter((id) => {
      const a = agents.get(id);
      return a && !a.pinned && !ARCHIVED.has(a.status);
    })
    .sort(byRecency);
  const archivedIds = agentOrder
    .filter((id) => {
      const a = agents.get(id);
      return a && !a.pinned && ARCHIVED.has(a.status);
    })
    .sort(byRecency);

  // Close context menu on click-outside or Escape
  useEffect(() => {
    if (!ctxMenu) return;
    function handleClick(e: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setCtxMenu(null);
      }
    }
    function handleKey(e: KeyboardEvent) {
      if (e.key === "Escape") setCtxMenu(null);
    }
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleKey);
    };
  }, [ctxMenu]);

  const openMenu = useCallback((agentId: string, x: number, y: number) => {
    setCtxMenu({ agentId, x, y });
  }, []);

  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
    e.preventDefault();
    openMenu(agentId, e.clientX, e.clientY);
  }, [openMenu]);

  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
    e.stopPropagation();
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    openMenu(agentId, rect.right, rect.bottom);
  }, [openMenu]);

  const closeMenu = useCallback(() => setCtxMenu(null), []);

  function renderAgentRow(id: string, dimmed: boolean) {
    const agent = agents.get(id);
    if (!agent) return null;
    const isActive = id === activeAgentId;
    return (
      <div
        key={id}
        onClick={() => onSelect(id)}
        onContextMenu={(e) => handleContextMenu(e, id)}
        className={cn(
          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
          dimmed && "opacity-60"
        )}
      >
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="flex items-center gap-2">
            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
            {renamingId === id ? (
              <RenameInput
                initialValue={agent.label}
                onConfirm={(label) => {
                  onRename(id, label);
                  setRenamingId(null);
                }}
                onCancel={() => setRenamingId(null)}
              />
            ) : (
              <span className="truncate">{agent.label || "new agent"}</span>
            )}
            {agent.pinned && (
              <Pin className="size-2.5 shrink-0 text-muted-foreground" />
            )}
          </span>
          {agent.tmuxSession && (
            <span className="pl-4 text-[10px] text-muted-foreground truncate">
              {agent.tmuxSession}
            </span>
          )}
        </div>
        <button
          onClick={(e) => handleMenuButton(e, id)}
          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
          aria-label="Agent menu"
        >
          <EllipsisVertical className="size-3.5 text-muted-foreground" />
        </button>
      </div>
    );
  }

  return (
    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
      {/* Workspace switcher */}
      <div className="border-b">
        <WorkspaceSwitcher
          workspaces={workspaces}
          activeWorkspaceId={activeWorkspaceId}
          onSelect={onSelectWorkspace}
          onRename={onRenameWorkspace}
          onDelete={onDeleteWorkspace}
          onOpenFolder={onOpenFolder}
        />
      </div>

      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2">
        <span className="text-xs font-semibold">agents</span>
        <button
          onClick={onNewAgent}
          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
          aria-label="New agent"
        >
          <Plus className="size-3.5" />
        </button>
      </div>

      {/* Agent list */}
      <div className="flex-1 overflow-y-auto">
        {loading ? (
          <div className="space-y-1 px-3 py-2">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="flex items-center gap-2 py-2">
                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
              </div>
            ))}
          </div>
        ) : agentOrder.length === 0 ? (
          <div className="px-3 py-4 text-xs text-muted-foreground">
            No agents yet
          </div>
        ) : null}

        {/* Pinned agents */}
        {pinnedIds.length > 0 && (
          <>
            <div className="flex items-center gap-2 px-3 pt-2 pb-1">
              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">pinned</span>
              <div className="flex-1 border-t" />
            </div>
            {pinnedIds.map((id) => renderAgentRow(id, false))}
          </>
        )}

        {/* Active agents */}
        {activeIds.length > 0 && (
          <>
            {pinnedIds.length > 0 && (
              <div className="flex items-center gap-2 px-3 pt-3 pb-1">
                <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">active</span>
                <div className="flex-1 border-t" />
              </div>
            )}
            {activeIds.map((id) => renderAgentRow(id, false))}
          </>
        )}

        {/* Archived divider + agents */}
        {archivedIds.length > 0 && (
          <>
            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
              <div className="flex-1 border-t" />
            </div>
            {archivedIds.map((id) => renderAgentRow(id, true))}
          </>
        )}
      </div>

      {/* Context menu */}
      {ctxMenu && (() => {
        const agent = agents.get(ctxMenu.agentId);
        if (!agent) return null;
        return (
          <div
            ref={menuRef}
            className="fixed z-[100] min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
            style={{ left: ctxMenu.x, top: ctxMenu.y }}
          >
            <ContextMenuItem
              label={agent.pinned ? "Unpin" : "Pin"}
              onClick={() => {
                onPin(ctxMenu.agentId, !agent.pinned);
                closeMenu();
              }}
            />
            <ContextMenuItem
              label="Rename"
              onClick={() => {
                setRenamingId(ctxMenu.agentId);
                closeMenu();
              }}
            />
            {KILLABLE.has(agent.status) && (
              <ContextMenuItem
                label="Kill"
                onClick={() => {
                  onKill(ctxMenu.agentId);
                  closeMenu();
                }}
              />
            )}
            <ContextMenuItem
              label="Clear History"
              onClick={() => {
                onClearHistory(ctxMenu.agentId);
                closeMenu();
              }}
            />
            <div className="my-1 border-t" />
            <ContextMenuItem
              label="Delete"
              destructive
              onClick={() => {
                closeMenu();
                if (confirm("Delete this agent? This cannot be undone.")) {
                  onDelete(ctxMenu.agentId);
                }
              }}
            />
          </div>
        );
      })()}
    </div>
  );
}

/** A single item in the context menu. */
function ContextMenuItem({
  label,
  onClick,
  destructive,
}: {
  label: string;
  onClick: () => void;
  destructive?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "flex w-full px-3 py-1.5 text-xs transition-colors",
        destructive
          ? "text-red-500 hover:bg-red-500/10"
          : "hover:bg-accent"
      )}
    >
      {label}
    </button>
  );
}

/** Inline input for renaming an agent. */
function RenameInput({
  initialValue,
  onConfirm,
  onCancel,
}: {
  initialValue: string;
  onConfirm: (value: string) => void;
  onCancel: () => void;
}) {
  const [value, setValue] = useState(initialValue);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  function handleKeyDown(e: React.KeyboardEvent) {
    e.stopPropagation();
    if (e.key === "Enter") {
      const trimmed = value.trim();
      if (trimmed) onConfirm(trimmed);
      else onCancel();
    } else if (e.key === "Escape") {
      onCancel();
    }
  }

  return (
    <input
      ref={inputRef}
      type="text"
      value={value}
      onChange={(e) => setValue(e.target.value)}
      onKeyDown={handleKeyDown}
      onBlur={() => {
        const trimmed = value.trim();
        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
        else onCancel();
      }}
      onClick={(e) => e.stopPropagation()}
      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
    />
  );
}

input.old_string:
  /** Whether this agent is pinned to the top of the sidebar. */
  pinned?: boolean;
}

input.new_string:
  /** Whether this agent is pinned to the top of the sidebar. */
  pinned?: boolean;
  /** Whether this agent is in the icebox (parked for later). */
  iceboxed?: boolean;
}

tool_use_result.oldString:
  /** Whether this agent is pinned to the top of the sidebar. */
  pinned?: boolean;
}

tool_use_result.newString:
  /** Whether this agent is pinned to the top of the sidebar. */
  pinned?: boolean;
  /** Whether this agent is in the icebox (parked for later). */
  iceboxed?: boolean;
}

tool_use_result.originalFile:
/**
 * Shared type definitions for the thos dashboard.
 *
 * Three categories:
 * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
 *    `--sdk-url` WebSocket connection (CLI → WS server).
 * 2. **Browser ↔ Server** — messages exchanged between the React client
 *    and the standalone WS relay server.
 * 3. **UI state** — view-model types consumed by React components.
 *
 * ## Key architecture notes
 *
 * - On browser connect, the server sends `agent_list` + `task_list` only.
 * - Message histories are loaded lazily: the browser sends
 *   `request_history` when selecting an agent, and the server responds
 *   with `message_history` for that single agent.
 * - Live messages for active agents are broadcast via `relay` in real time.
 * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 */

// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────

/**
 * Sent once after the first user prompt is received. Contains session
 * metadata like the model name, working directory, and available tools.
 */
export interface ClaudeSystemInit {
  type: "system";
  subtype: "init";
  session_id: string;
  tools: unknown[];
  mcp_servers: unknown[];
  model: string;
  cwd: string;
}

/**
 * An assistant turn. `message.content` is an array of content blocks
 * (text, tool_use, tool_result) that may arrive incrementally — each
 * NDJSON line is a complete snapshot of the message so far.
 */
export interface ClaudeAssistant {
  type: "assistant";
  message: {
    id: string;
    role: "assistant";
    content: AssistantContentBlock[];
    model: string;
    stop_reason: string | null;
  };
  session_id: string;
}

/** A single content block inside an assistant message. */
export type AssistantContentBlock =
  | { type: "text"; text: string }
  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
  | { type: "tool_result"; tool_use_id: string; content: string };

/**
 * Terminal message for a session. Includes cost/duration metrics.
 * `is_error` is true when `subtype` is `"error"`.
 */
export interface ClaudeResult {
  type: "result";
  subtype: "success" | "error";
  result?: string;
  error?: string;
  session_id: string;
  cost_usd: number;
  total_cost_usd?: number;
  duration_ms: number;
  duration_api_ms: number;
  is_error: boolean;
  num_turns: number;
}

/**
 * Claude is requesting permission to execute a tool. The dashboard must
 * reply with a `control_response` (allow / deny) before the CLI proceeds.
 *
 * Wire format uses a nested `request` object with `request_id` at the
 * top level for correlation (matches Companion protocol docs).
 */
export interface ClaudeControlRequest {
  type: "control_request";
  request_id: string;
  request: {
    subtype: "can_use_tool";
    tool_name: string;
    input: Record<string, unknown>;
    tool_use_id?: string;
    description?: string;
  };
  session_id?: string;
}

/**
 * Hook lifecycle events emitted during CLI startup. `hook_response` is
 * the signal that the CLI is ready to receive the first user prompt.
 */
export interface ClaudeSystemHook {
  type: "system";
  subtype: "hook_started" | "hook_response";
  session_id?: string;
}

/** Discriminated union of all known Claude NDJSON message shapes. */
export type ClaudeMessage =
  | ClaudeSystemInit
  | ClaudeAssistant
  | ClaudeResult
  | ClaudeControlRequest
  | ClaudeSystemHook
  | { type: string; subtype?: string; [key: string]: unknown };

// ── Workspaces ───────────────────────────────────────────────────────────

/** A workspace represents a project directory. */
export interface Workspace {
  id: string;
  name: string;
  cwd: string;
  createdAt: number;
}

/** A directory entry returned by the server-side folder browser. */
export interface DirectoryEntry {
  name: string;
  path: string;
}

// ── Browser ↔ Server messages ─────────────────────────────────────────────

/** Browser asks the server to spawn a new Claude CLI process. */
export interface BrowserSpawn {
  type: "spawn";
  prompt: string;
  workspaceId?: string;
  /** Optional model override (e.g. "claude-opus-4-20250514", "qwen3-coder"). */
  model?: string;
}

/** Browser sends a follow-up message to an already-running Claude session. */
export interface BrowserSendMessage {
  type: "send_message";
  agentId: string;
  content: string;
}

/** Browser responds to a tool approval request (allow or deny). */
export interface BrowserControlResponse {
  type: "control_response";
  agentId: string;
  request_id: string;
  allow: boolean;
}

/** Browser asks the server to kill a running agent's tmux session + CLI. */
export interface BrowserKillAgent {
  type: "kill_agent";
  agentId: string;
}

/** Browser asks the server to permanently delete an agent. */
export interface BrowserDeleteAgent {
  type: "delete_agent";
  agentId: string;
}

/** Browser asks the server to rename an agent. */
export interface BrowserRenameAgent {
  type: "rename_agent";
  agentId: string;
  label: string;
}

/** Browser asks the server to clear an agent's message history. */
export interface BrowserClearHistory {
  type: "clear_history";
  agentId: string;
}

/** Browser asks the server to pin or unpin an agent. */
export interface BrowserPinAgent {
  type: "pin_agent";
  agentId: string;
  pinned: boolean;
}

/** Browser requests message history for a specific agent (lazy loading). */
export interface BrowserRequestHistory {
  type: "request_history";
  agentId: string;
}

/** Browser asks the server to create a new task. */
export interface BrowserCreateTask {
  type: "create_task";
  title: string;
  description: string;
  priority: TaskPriority;
}

/** Browser asks to update a task's fields. */
export interface BrowserUpdateTask {
  type: "update_task";
  taskId: string;
  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
}

/** Browser asks to delete a task. */
export interface BrowserDeleteTask {
  type: "delete_task";
  taskId: string;
}

/** Browser asks to delegate a task to a new Claude agent. */
export interface BrowserDelegateTask {
  type: "delegate_task";
  taskId: string;
}

/** Browser tells the server which workspace to scope to. */
export interface BrowserSetWorkspace {
