              <div className="flex-1 border-t" />
            </div>
            {pinnedIds.map((id) => renderAgentRow(id, false))}
          </>
        )}

        {/* Active agents */}
        {activeIds.length > 0 && (
          <>
            {pinnedIds.length > 0 && (
