    .filter((id) => {
      const a = agents.get(id);
      return a && a.pinned && !a.iceboxed;
    })
    .sort(byRecency);
  const activeIds = agentOrder
    .filter((id) => {
      const a = agents.get(id);
      return a && !a.pinned && !a.iceboxed && !ARCHIVED.has(a.status);
    })
    .sort(byRecency);
  const iceboxIds = agentOrder
    .filter((id) => {
      const a = agents.get(id);
      return a && a.iceboxed;
    })
    .sort(byRecency);
  const archivedIds = agentOrder
    .filter((id) => {
      const a = agents.get(id);
      return a && !a.pinned && !a.iceboxed && ARCHIVED.has(a.status);
    })
    .sort(byRecency);

